/**
 * Permite revisar casos de Universidad a Emérito sin tocar los demás desafíos.
 * Los casos se muestran una sola vez por combinación de área y etapa.
 */
export function researchCaseFor(areaId:string,stageIndex:number):ResearchCaseRow|null{
 if(!Number.isInteger(stageIndex)||stageIndex<4||stageIndex>13)return null;
 return CASES[areaId]?.[stageIndex-4]??null;
}

/**
 * Diagnóstico para CI: evita casos faltantes, opciones duplicadas y consejos
 * vacíos. La revisión semántica sigue requiriendo docentes especialistas.
 */
export function validateResearchCases(areaIds:readonly string[]):string[]{
 const errors:string[]=[];
 const questions=new Set<string>();
 for(const id of areaIds){
  const rows=CASES[id];
  if(!rows||rows.length!==10){errors.push(`${id}: se esperaban 10 casos`);continue;}
  for(let i=0;i<10;i++){
   const item=rows[i];
   if(!item||item.length!==7||item.some(part=>part.trim().length<20)){
    errors.push(`${id}:${i+4}: caso incompleto`);continue;
   }
   if(new Set(item.slice(2,5)).size!==3)errors.push(`${id}:${i+4}: opciones repetidas`);
   if(questions.has(item[1]))errors.push(`${id}:${i+4}: pregunta duplicada`);
   questions.add(item[1]);
  }
 }
 return errors;
}